async function load(): Promise<void> {
  loading.value = true; error.value = null; notFound.value = false;
  try { const p = await warehouseLiteApi.detail(route.params.id as string); row.value = p; Object.assign(form, {code: p.code, name: p.name, address: p.address, manager: p.manager, status: p.status }); }
  catch (e) { error.value = errorMessage(e); if (e instanceof Error && 'status' in e && (e as { status: number }).status === 404) { notFound.value = true; } }
  finally { loading.value = false; }
}

async function submit(): Promise<void> {
  if (!row.value) return;
  submitting.value = true; formError.value = null;
  try { await warehouseLiteApi.update(row.value.id, {code: form.code, name: form.name, address: form.address, manager: form.manager, status: form.status }); notifySuccess('WarehouseLites updated'); router.push({ path: '/warehouse-lite/' + row.value.id }); }
  catch (e) { formError.value = errorMessage(e); } finally { submitting.value = false; }
}

onMounted(load);
